import {fetchGoogleWeather} from './google-weather.mjs';
export const googleState={key:'',points:new Map(),fetched:0,busy:false,controller:null,error:'',done:0,total:0};
export const pointKey=p=>`${p.id}|${p.lat}|${p.lon}`;
export function clearGoogle(){googleState.controller?.abort();googleState.points.clear();googleState.fetched=0;googleState.error=''}
export async function fetchGoogleRoute(s,{signal,onProgress=()=>{},fetchPoint=fetchGoogleWeather}={}){if(!googleState.key.trim())throw Error('Google API key required');if(googleState.busy)return;googleState.busy=true;googleState.done=0;googleState.total=s.sites.length;googleState.error='';googleState.points.clear();let controller=new AbortController();googleState.controller=controller;const abort=()=>controller.abort();signal?.addEventListener('abort',abort);if(signal?.aborted)abort();try{for(let p of s.sites){if(controller.signal.aborted)break;try{let data=await fetchPoint({lat:p.lat,lon:p.lon,key:googleState.key,hours:168,lang:s.lang,signal:controller.signal});if(!controller.signal.aborted){try{let prior=await fetchPoint({lat:p.lat,lon:p.lon,key:googleState.key,hours:24,history:true,lang:s.lang,signal:controller.signal});data.history=prior.rows;data.requests+=prior.requests}catch(e){googleState.error+=`${p.pk} history: ${e.message}\n`;if(/HTTP (401|403|429)/.test(e.message))controller.abort()}googleState.points.set(pointKey(p),data)}}catch(e){googleState.error+=`${p.pk}: ${e.message}\n`;if(/HTTP (401|403|429)/.test(e.message))break}googleState.done++;onProgress();}googleState.fetched=Date.now()}finally{signal?.removeEventListener('abort',abort);googleState.busy=false;googleState.controller=null;onProgress()}}
export function googleRows(p,now=Date.now(),count=192){const f=googleState.points.get(pointKey(p));let map=new Map([...(f?.history||[]),...(f?.rows||[])].map(h=>[h.t,h]));let start=(Math.floor(now/3600000)+1)*3600;return Array.from({length:count},(_,i)=>{let t=start+i*3600,h=map.get(t),prev=Array.from({length:24},(_,j)=>map.get(t-(j+1)*3600)?.rain);return {t,google:h||null,googleStale:!f||now-f.fetched>43200000,googleWet:prev.every(v=>typeof v==='number'&&Number.isFinite(v))?prev.reduce((a,b)=>a+b,0):null}})}
export function googleRisk(row,s,p,activity){let h=row.google,level=0,reasons=[],missing=row.googleStale||!h;const valid=x=>typeof x==='number'&&Number.isFinite(x);const add=(l,r)=>{level=Math.max(level,l);reasons.push(r)};if(h){if(h.thunderstorm)add(2,'googleThunder');if(valid(h.thunder)&&h.thunder>=30)add(1,'googleThunderRisk');if(h.rain>=(p.rainRed??s.rainRed)||h.prob>s.probRed)add(2,'rainRed');else if(h.rain>=s.rainYellow||h.prob>=s.probYellow)add(1,'rainYellow');missing||=!valid(h.rain)||!valid(h.prob)||!h.condition;if(['lifting','emulsion'].includes(activity)){if(Math.max(h.wind??0,h.gust??0)>s.wind)add(2,'wind');missing||=!valid(h.wind)||!valid(h.gust)}if(activity==='asphalt'){if(valid(h.temp)&&h.temp<s.asphalt)add(2,'cold');missing||=!valid(h.temp)}if(activity==='concrete'){if(valid(h.temp)&&h.temp>s.concrete)add(1,'hot');missing||=!valid(h.temp)}if(['earth','asphalt'].includes(activity)){if(row.googleWet>=(p.wet24??s.wet24))add(1,'wet');missing||=!valid(row.googleWet)}}if(missing){if(level!==2)level=-1;reasons.push(row.googleStale?'stale':'missing')}return {level,reasons:reasons.length?reasons:['ok']}}
